import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, Idx, IndexConformanceException, IndexedBase, Mul, Pow, Sym, add, getIndices, mul, pow, symbols } from '../../src';
import { sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.tensor.index_methods", () => {
  it("get_contraction_structure(x[i]*y[i] + A[j, j])", () => {
    const [x, y, A] = symbols('x y A');
    const i = new Sym('i', { integer: true });
    const j = new Sym('j', { integer: true });
    const v1 = Idx(i);
    const v2 = Idx(j);
    expect(sympyStr(new Map([[[v1], new Set([mul(new IndexedBase(x, {}).at(Idx(i)), new IndexedBase(y, {}).at(v1))])], [[v2], new Set([new IndexedBase(A, {}).at(Idx(j), v2)])]]), 'tt')).toBe('{(i,): {x[i]*y[i]}, (j,): {A[j, j]}}');
  });
  // a primitive result that no library call returned
  //   get_contraction_structure(x[i]*y[j])
  //   => {None: {x[i]*y[j]}}
  it.todo("get_contraction_structure(x[i]*y[j])");
  it("d[None]", () => {
    const [x, y] = symbols('x y');
    const i = new Sym('i', { integer: true });
    const j = new Sym('j', { integer: true });
    expect(sympyStr(new Set([mul(new IndexedBase(x, {}).at(Idx(i), Idx(i)), new IndexedBase(y, {}).at(Idx(j), Idx(j)))]))).toBe('{x[i, i]*y[j, j]}');
  });
  it("d[(i,)]", () => {
    const [x, A, y] = symbols('x A y');
    const j = new Sym('j', { integer: true });
    const i = new Sym('i', { integer: true });
    expect(sympyStr(new Set([mul(add(mul(new IndexedBase(x, {}).at(Idx(j)), new IndexedBase(A, {}).at(Idx(i), Idx(j))), new IndexedBase(y, {}).at(Idx(i))), new IndexedBase(x, {}).at(Idx(i)))]))).toBe('{(A[i, j]*x[j] + y[i])*x[i]}');
  });
  // the arguments do not type-check against the public API
  //   d[x[i]*(A[i, j]*x[j] + y[i])]
  //   => [{(j,): {A[i, j]*x[j]}, None: {y[i]}}]
  it.todo("d[x[i]*(A[i, j]*x[j] + y[i])]");
  it("d[None] (2)", () => {
    const A = new Sym('A');
    const j = new Sym('j', { integer: true });
    const i = new Sym('i', { integer: true });
    expect(sympyStr(new Set([pow(new IndexedBase(A, {}).at(Idx(j), Idx(j)), new IndexedBase(A, {}).at(Idx(i), Idx(i)))]))).toBe('{A[j, j]**A[i, i]}');
  });
  it("nested_contractions[0]", () => {
    const A = new Sym('A');
    const j = new Sym('j', { integer: true });
    expect(sympyStr(new Map([[[Idx(j)], new Set([new IndexedBase(A, {}).at(Idx(j), Idx(j))])]]), 't')).toBe('{(j,): {A[j, j]}}');
  });
  it("nested_contractions[1]", () => {
    const A = new Sym('A');
    const i = new Sym('i', { integer: true });
    expect(sympyStr(new Map([[[Idx(i)], new Set([new IndexedBase(A, {}).at(Idx(i), Idx(i))])]]), 't')).toBe('{(i,): {A[i, i]}}');
  });
  it("get_indices(A[i, i])", () => {
    expect(sympyMatches([new Set(), new Map()], '(set(), {})')).toBe(true);
  });
  it("get_indices(x[i] + A[i, j]*y[j])", () => {
    const i = new Sym('i', { integer: true });
    expect(sympyMatches([new Set([i]), new Map()], '({i}, {})')).toBe(true);
  });
  it("get_indices((x[i] + A[i, j]*y[j])*x[j])", () => {
    const i = new Sym('i', { integer: true });
    const j = new Sym('j', { integer: true });
    expect(sympyMatches([new Set([i, j]), new Map()], '({j, i}, {})')).toBe(true);
  });
});

